+    void rejectsReservationsWithIncompleteIdentification() throws Exception {
+        String cnpjOnly = """
+                {"roomNumber": 201, "guestName": "Ana", "guestEmail": "ana@example.com",
+                 "companyCnpj": "12.345.678/0001-90", "checkIn": "2027-03-10", "checkOut": "2027-03-12",
+                 "guests": 2, "ratePlan": "STANDARD"}
+                """;
+        HttpResponse<String> response = post("/reservations", cnpjOnly);
+        assertEquals(400, response.statusCode());
+        assertEquals("INVALID_REQUEST", json.readTree(response.body()).get("error").asText());
+    }
 }

